import sys,json; sys.path.insert(0,'/tmp/dbtest')
exec(open('/tmp/dbtest/e2e_full.py').read().split("# ---------- seed")[0])
def ok_(name,sql,sub=OWNER,role='authenticated',expect=True,show=False):
    ok,r=call(role,sql,sub=sub); check(name, ok==expect, r)
    if show: print('   ->',str(r)[:200])
    return r
print('=== T2. Maintenance visit')
VIS=q1("select id from public.maintenance_plan_visits order by created_at desc limit 1")
ok_('maintenance visit completed',f"select public.complete_maintenance_visit_360('{VIS}',current_date,'All good')",show=True)
print('=== U. Invoice -> payment (finance operations)')
CUS=q1("select id from public.customers order by created_at limit 1")
inv=ok_('invoice created (16% VAT)',f"select public.create_invoice_transaction('{CUS}',NULL,NULL,'Jane Wanjiru','jane@example.co.ke','0712345678','Nairobi',16,current_date+14,'Floor coating')",show=True)
INV=q1("select id from public.invoices order by created_at desc limit 1")
ok_('a draft invoice with no items cannot be sent',f"select public.transition_invoice_lifecycle('{INV}','sent',NULL)",expect=False,show=True)
ok_('line item added',f"select public.add_invoice_item_transaction('{INV}','Epoxy coating 100 sqm',100,1000)")
t=q1(f"select subtotal||'/'||tax_amount||'/'||total_amount from public.invoices where id='{INV}'"); print('   subtotal/tax/total:',t)
check('VAT is calculated at 16%', t=='100000.00/16000.00/116000.00', t)
ok_('draft cannot be marked paid',f"select public.transition_invoice_lifecycle('{INV}','paid',NULL)",expect=False,show=True)
ok_('invoice sent',f"select public.transition_invoice_lifecycle('{INV}','sent',NULL)")
ok_('payment above the balance refused',f"select public.record_invoice_payment_transaction('{INV}',200000,'bank_transfer','BANK-1',NULL)",expect=False,show=True)
ok_('partial payment recorded',f"select public.record_invoice_payment_transaction('{INV}',50000,'bank_transfer','BANK-1',NULL)",show=True)
check('invoice is partial with the right balance', q1(f"select status||'/'||balance_due from public.invoices where id='{INV}'")=='partial/66000.00', q1(f"select status||'/'||balance_due from public.invoices where id='{INV}'"))
ok_('cash payment without a reference allowed',f"select public.record_invoice_payment_transaction('{INV}',66000,'cash',NULL,NULL)",show=True)
check('invoice is paid with zero balance', q1(f"select status||'/'||balance_due from public.invoices where id='{INV}'")=='paid/0.00', q1(f"select status||'/'||balance_due from public.invoices where id='{INV}'"))
PAY=q1(f"select id from public.invoice_payments where invoice_id='{INV}' order by created_at desc limit 1") if q1("select to_regclass('public.invoice_payments')") else None
print('   receipt/notification rows mentioning payment or invoice:',q1("select count(*) from public.communication_outbox where subject ilike '%invoice%' or subject ilike '%payment%' or subject ilike '%receipt%'"))
ok_('finance operations snapshot loads',f"select public.get_finance_operations_360(30)")
ok_('a customer-role user cannot read finance operations',f"select public.get_finance_operations_360(30)",sub='44444444-4444-4444-4444-444444444444',expect=False,show=True)
ok_('anonymous cannot read finance operations',f"select public.get_finance_operations_360(30)",role='anon',sub=None,expect=False)
print(f"\n{sum(1 for _,c in results if c)}/{len(results)} checks passed")
